/**
 * About and licenses: the generated open-source lists, and the `foss`-only releases link.
 *
 * Play, the App Store and F-Droid update the app themselves; a `foss` build says so and adds
 * one static link to the canonical repository's releases, opened in the system browser. There
 * is no update check and nothing built from fetched data, so nothing to spoof (T50).
 *
 * - The lists are generated by `mobile/scripts/licenses.sh` into `src/generated/licenses/`.
 *
 * <module-headers:begin>
 * Uses:
 * src/screens/settings/Licenses.tsx
 * ├── @yaran/secure-store:src/index.ts
 * ├── mobile/app/src/generated/licenses/android-foss.json
 * ├── mobile/app/src/generated/licenses/android-play.json
 * ├── mobile/app/src/generated/licenses/ios.json
 * ├── mobile/app/src/generated/licenses/js.json
 * ├── src/lib/buildInfo.ts
 * └── src/screens/Page.tsx
 * External: @lingui/react, react
 *
 * Used by:
 * src/screens/settings/Licenses.tsx
 * ├── src/App.tsx
 * └── src/screens/settings/settings.test.tsx
 * <module-headers:end>
 */
import { Trans } from '@lingui/react/macro';
import type { Flavor } from '@yaran/secure-store';
import { useEffect, useState, type ReactNode } from 'react';

import androidFoss from '../../generated/licenses/android-foss.json' with { type: 'json' };
import androidPlay from '../../generated/licenses/android-play.json' with { type: 'json' };
import ios from '../../generated/licenses/ios.json' with { type: 'json' };
import js from '../../generated/licenses/js.json' with { type: 'json' };
import { loadBuildInfo } from '../../lib/buildInfo.ts';
import { Page } from '../Page.tsx';

export const RELEASES_URL = 'https://github.com/SiavZ/yaran/releases';

interface LicenseEntry {
  name: string;
  version: string;
  license: string;
}
interface LicenseList {
  generated: string;
  entries: LicenseEntry[];
}

function List({ title, list }: { title: ReactNode; list: LicenseList }) {
  return (
    <section className="flex flex-col gap-1">
      <h2 className="font-semibold">{title}</h2>
      <ul className="text-sm">
        {list.entries.map((e) => (
          <li key={`${e.name}@${e.version}`} className="flex justify-between gap-2 py-0.5">
            <span>
              {e.name} <span className="text-muted-foreground">{e.version}</span>
            </span>
            <span className="text-muted-foreground">{e.license}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}

export function Licenses() {
  const [flavor, setFlavor] = useState<Flavor | null>(null);
  useEffect(() => void loadBuildInfo().then((b) => setFlavor(b.flavor)), []);
  const native = flavor === 'appstore' ? ios : flavor === 'play' ? androidPlay : androidFoss;
  return (
    <Page title={<Trans>About and licenses</Trans>}>
      {flavor === 'foss' && (
        <section className="flex flex-col gap-2">
          <p className="text-sm text-muted-foreground">
            <Trans>
              This build doesn't update itself. If you installed it from F-Droid, F-Droid updates it; if you installed it by hand,
              new versions are published on GitHub.
            </Trans>
          </p>
          <a className="inline-flex min-h-10 items-center text-primary underline" href={RELEASES_URL} target="_blank" rel="noreferrer noopener">
            <Trans>Releases on GitHub</Trans>
          </a>
        </section>
      )}
      <List title={<Trans>App interface</Trans>} list={js as LicenseList} />
      <List title={<Trans>Native components</Trans>} list={native as LicenseList} />
    </Page>
  );
}
